// Enhanced Command Parser - Supports all CTO commands
try {
  const noteData = $input.first().json.body || $input.first().json;
  const noteBody = (noteData.object_attributes?.note || '').trim();
  const noteLower = noteBody.toLowerCase();
  const authorUsername = noteData.user?.username || '';
  const mrIid = noteData.merge_request?.iid;
  const projectId = noteData.project_id;

  // Get authorized approvers from environment
  const authorizedApprovers = ($('Config').first().json.AUTHORIZED_APPROVERS || 'cto,tech-lead').split(',').map(s => s.trim().toLowerCase());

  // Parse result
  let result = {
    action: 'ignore',
    reason: 'not_a_command',
    review_id: null,
    mr_iid: mrIid,
    project_id: projectId,
    author: authorUsername,
    note_id: noteData.object_attributes?.id,
    gitlab_url: $('Config').first().json.GITLAB_URL,
    // Command-specific data
    selected_findings: [],
    custom_comment: null,
    edit_data: null,
    remove_ids: []
  };

  // Extract review_id from note (format: review-xxx-xxx-xxx)
  const reviewIdMatch = noteBody.match(/review-[\w-]+/);
  if (reviewIdMatch) {
    result.review_id = reviewIdMatch[0];
  }

  // Parse range notation (e.g., "1,3,5-7" -> [1,3,5,6,7])
  function parseIdRange(str) {
    const ids = [];
    const parts = str.split(',').map(s => s.trim());
    for (const part of parts) {
      if (part.includes('-')) {
        const [start, end] = part.split('-').map(n => parseInt(n.trim()));
        if (!isNaN(start) && !isNaN(end)) {
          for (let i = start; i <= end; i++) ids.push(i);
        }
      } else {
        const num = parseInt(part);
        if (!isNaN(num)) ids.push(num);
      }
    }
    return [...new Set(ids)].sort((a, b) => a - b);
  }

  // Detect command type
  if (noteLower.startsWith('!approve-partial')) {
    // /approve-partial 1,3,5-7
    const match = noteBody.match(/!approve-partial\s+([\d,\-\s]+)/);
    if (match) {
      result.action = 'approve_partial';
      result.selected_findings = parseIdRange(match[1]);
    } else {
      result.action = 'error';
      result.reason = 'Invalid format. Use: !approve-partial 1,3,5-7';
    }
  } else if (noteLower.startsWith('!approve')) {
    result.action = 'approve_all';
  } else if (noteLower.startsWith('!reject')) {
    result.action = 'reject';
  } else if (noteLower.startsWith('!remove-finding')) {
    // /remove-finding 2,4,6
    const match = noteBody.match(/!remove-finding\s+([\d,\-\s]+)/);
    if (match) {
      result.action = 'remove_finding';
      result.remove_ids = parseIdRange(match[1]);
    } else {
      result.action = 'error';
      result.reason = 'Invalid format. Use: !remove-finding 1,2,3';
    }
  } else if (noteLower.startsWith('!edit-finding')) {
    // /edit-finding 3 severity:low title:"New title"
    const match = noteBody.match(/!edit-finding\s+(\d+)\s+(.+)/);
    if (match) {
      const findingId = parseInt(match[1]);
      const changesStr = match[2];
      const changes = {};

      // Parse key:value pairs
      const severityMatch = changesStr.match(/severity:(critical|high|medium|low)/i);
      if (severityMatch) changes.severity = severityMatch[1].toLowerCase();

      const titleMatch = changesStr.match(/title:"([^"]+)"/);
      if (titleMatch) changes.title = titleMatch[1];

      const descMatch = changesStr.match(/description:"([^"]+)"/);
      if (descMatch) changes.description = descMatch[1];

      result.action = 'edit_finding';
      result.edit_data = { id: findingId, changes: changes };
    } else {
      result.action = 'error';
      result.reason = 'Invalid format. Use: !edit-finding 1 severity:low';
    }
  } else if (noteLower.startsWith('!add-comment')) {
    // /add-comment src/file.js:42 "Your comment here"
    const match = noteBody.match(/!add-comment\s+(\S+):(\d+)\s+"([^"]+)"/);
    if (match) {
      result.action = 'add_comment';
      result.custom_comment = {
        file_path: match[1],
        line: parseInt(match[2]),
        message: match[3]
      };
    } else {
      result.action = 'error';
      result.reason = 'Invalid format. Use: !add-comment file.js:42 "Your comment"';
    }
  } else if (noteLower.startsWith('!list-findings')) {
    result.action = 'list_findings';
  } else if (noteLower.startsWith('!explain')) {
    const match = noteBody.match(/!explain\s+(\d+)/);
    if (match) {
      result.action = 'explain';
      result.explain_finding_id = parseInt(match[1]);
    } else {
      result.action = 'error';
      result.reason = 'Invalid format. Use: !explain <finding-id>';
    }
  } else if (noteLower.startsWith('!rerun-agent')) {
    const match = noteBody.match(/!rerun-agent\s+(security|performance|style|architecture|test-coverage|code-quality|context)/i);
    if (match) {
      result.action = 'rerun_agent';
      result.rerun_agent_name = match[1].toLowerCase();
    } else {
      result.action = 'error';
      result.reason = 'Valid agents: security, performance, style, architecture, test-coverage, code-quality, context';
    }
  } else {
    // Not a command we recognize
    result.action = 'ignore';
    result.reason = 'not_a_command';
  }

  // Check authorization for non-ignore actions
  if (result.action !== 'ignore' && result.action !== 'error') {
    if (!authorizedApprovers.includes(authorUsername.toLowerCase())) {
      result.action = 'unauthorized';
      result.reason = `User @${authorUsername} is not authorized. Authorized: ${authorizedApprovers.join(', ')}`;
    }
  }

  return [{ json: result }];
} catch (error) {
  return [{ json: { action: 'error', reason: `Parse error: ${error.message}`, error: true } }];
}

// Prepare ALL inline comments for posting
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id } }];
  }

  const findings = JSON.parse(reviewData.findings);
  const customComments = reviewData.custom_comments ? JSON.parse(reviewData.custom_comments) : [];

  const allComments = prepareComments(findings, customComments, reviewData, cmdData);

  return allComments.map(c => ({ json: c }));
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'prepare_all_comments' } }];
}

function prepareComments(findings, customComments, reviewData, cmdData) {
  const comments = [];
  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  const catEmoji = { 'security': '🔒', 'performance': '⚡', 'architecture': '🏗️', 'code-quality': '✨', 'test-coverage': '🧪', 'style': '🎨' };

  // Add AI findings
  for (const f of findings) {
    comments.push({
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid,
      body: `${sevEmoji[f.severity] || '⚪'} ${catEmoji[f.category] || '📋'} **[${f.id}] ${f.title}**\n\n**Severity:** ${f.severity}\n**Category:** ${f.category}\n\n${f.description}\n\n**Suggestion:** ${f.suggestion || 'N/A'}\n\n---\n_AI Code Review_`,
      file_path: f.file_path,
      line: f.line,
      position: {
        base_sha: reviewData.base_sha,
        start_sha: reviewData.start_sha,
        head_sha: reviewData.head_sha,
        position_type: 'text',
        new_path: f.file_path,
        new_line: f.line
      }
    });
  }

  // Add custom CTO comments
  for (const c of customComments) {
    comments.push({
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid,
      body: `💬 **CTO Comment**\n\n${c.message}\n\n---\n_Added by @${cmdData.author}_`,
      file_path: c.file_path,
      line: c.line,
      position: {
        base_sha: reviewData.base_sha,
        start_sha: reviewData.start_sha,
        head_sha: reviewData.head_sha,
        position_type: 'text',
        new_path: c.file_path,
        new_line: c.line
      }
    });
  }

  return comments;
}

// Prepare PARTIAL inline comments (only selected IDs)
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id } }];
  }

  const allFindings = JSON.parse(reviewData.findings);
  const selectedIds = cmdData.selected_findings;
  const customComments = reviewData.custom_comments ? JSON.parse(reviewData.custom_comments) : [];

  // Filter to only selected findings
  const selectedFindings = allFindings.filter(f => selectedIds.includes(f.id));

  const allComments = prepareComments(selectedFindings, customComments, reviewData, cmdData);

  return allComments.map(c => ({ json: c }));
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'prepare_partial_comments' } }];
}

function prepareComments(findings, customComments, reviewData, cmdData) {
  const comments = [];
  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  const catEmoji = { 'security': '🔒', 'performance': '⚡', 'architecture': '🏗️', 'code-quality': '✨', 'test-coverage': '🧪', 'style': '🎨' };

  for (const f of findings) {
    comments.push({
      project_id: reviewData.project_id,
