// Remove specified findings from the list and update DB
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id, action: 'error' } }];
  }

  const allFindings = JSON.parse(reviewData.findings);
  const removeIds = cmdData.remove_ids;

  // Remove specified findings
  const remainingFindings = allFindings.filter(f => !removeIds.includes(f.id));

  // Re-number remaining findings
  const renumberedFindings = remainingFindings.map((f, idx) => ({ ...f, id: idx + 1 }));

  // Generate updated summary comment
  const summary = generateSummary(renumberedFindings, removeIds);

  return [{
    json: {
      review_id: cmdData.review_id,
      updated_findings: JSON.stringify(renumberedFindings),
      removed_count: removeIds.length,
      remaining_count: renumberedFindings.length,
      summary_comment: summary,
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid
    }
  }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'process_remove' } }];
}

function generateSummary(findings, removedIds) {
  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  let msg = `✅ **Removed findings:** ${removedIds.join(', ')}\n\n`;
  msg += `**Remaining findings (${findings.length}):**\n\n`;
  msg += `| # | Severity | File | Issue |\n|---|----------|------|-------|\n`;
  for (const f of findings) {
    msg += `| ${f.id} | ${sevEmoji[f.severity]} ${f.severity} | \`${f.file_path}:${f.line}\` | ${f.title} |\n`;
  }
  return msg;
}

// Edit specified finding and update DB
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id, action: 'error' } }];
  }

  const allFindings = JSON.parse(reviewData.findings);
  const editData = cmdData.edit_data;

  // Find and update the specified finding
  const updatedFindings = allFindings.map(f => {
    if (f.id === editData.id) {
      return { ...f, ...editData.changes };
    }
    return f;
  });

  // Generate confirmation message
  const editedFinding = updatedFindings.find(f => f.id === editData.id);
  let summary = `✅ **Updated finding #${editData.id}**\n\n`;
  if (editedFinding) {
    summary += `| Field | New Value |\n|-------|-----------|\n`;
    for (const [key, val] of Object.entries(editData.changes)) {
      summary += `| ${key} | ${val} |\n`;
    }
    summary += `\n**Current state:** ${editedFinding.severity} - ${editedFinding.title}`;
  }

  return [{
    json: {
      review_id: cmdData.review_id,
      updated_findings: JSON.stringify(updatedFindings),
      summary_comment: summary,
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid
    }
  }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'process_edit' } }];
}

// Add custom CTO comment to the list
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id, action: 'error' } }];
  }

  const customComments = reviewData.custom_comments ? JSON.parse(reviewData.custom_comments) : [];
  const newComment = cmdData.custom_comment;

  // Add the new comment
  customComments.push({
    file_path: newComment.file_path,
    line: newComment.line,
    message: newComment.message,
    added_by: cmdData.author,
    added_at: new Date().toISOString()
  });

  const summary = `✅ **Added custom comment**\n\n📁 \`${newComment.file_path}:${newComment.line}\`\n💬 "${newComment.message}"\n\n_Total custom comments: ${customComments.length}_`;

  return [{
    json: {
      review_id: cmdData.review_id,
      updated_custom_comments: JSON.stringify(customComments),
      summary_comment: summary,
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid
    }
  }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'process_add_comment' } }];
}

// Generate full findings list for display
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: 'Review not found', review_id: cmdData.review_id, action: 'error' } }];
  }

  const findings = JSON.parse(reviewData.findings);
  const customComments = reviewData.custom_comments ? JSON.parse(reviewData.custom_comments) : [];
  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  const catEmoji = { 'security': '🔒', 'performance': '⚡', 'architecture': '🏗️', 'code-quality': '✨', 'test-coverage': '🧪', 'style': '🎨' };

  let msg = `## 📋 Current Findings (${findings.length})\n\n`;
  msg += `| # | Severity | Category | File | Line | Issue |\n`;
  msg += `|---|----------|----------|------|------|-------|\n`;

  for (const f of findings) {
    msg += `| **${f.id}** | ${sevEmoji[f.severity]} ${f.severity} | ${catEmoji[f.category]} ${f.category} | \`${f.file_path}\` | ${f.line} | ${f.title} |\n`;
  }

  if (customComments.length > 0) {
    msg += `\n### 💬 Custom Comments (${customComments.length})\n\n`;
    for (let i = 0; i < customComments.length; i++) {
      const c = customComments[i];
      msg += `${i + 1}. \`${c.file_path}:${c.line}\` - "${c.message}" (by @${c.added_by})\n`;
    }
  }

  msg += `\n---\n*Review ID: \`${cmdData.review_id}\`*`;

  return [{
    json: {
      summary_comment: msg,
      project_id: reviewData.project_id,
      mr_iid: reviewData.mr_iid
    }
  }];
} catch (error) {
  return [{ json: { error: true, message: error.message, stage: 'process_list' } }];
}

