// Generate detailed explanation for a finding
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $input.first().json;

  if (!reviewData || !reviewData.findings) {
    return [{ json: { error: true, summary_comment: '⚠️ Review not found or no findings available.', gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
  }

  const findings = typeof reviewData.findings === 'string' ? JSON.parse(reviewData.findings) : reviewData.findings;
  const findingId = cmdData.explain_finding_id;
  const finding = findings.find(f => f.id === findingId);

  if (!finding) {
    return [{ json: { summary_comment: `⚠️ Finding #${findingId} not found. Use \`/list-findings\` to see available findings.`, gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
  }

  const sevEmoji = { critical: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
  const catEmoji = { 'security': '🔒', 'performance': '⚡', 'architecture': '🏗️', 'code-quality': '✨', 'test-coverage': '🧪', 'style': '🎨', 'context': '🔗' };

  let explanation = `## 🔍 Finding #${finding.id} - Detailed Explanation\n\n`;
  explanation += `### ${sevEmoji[finding.severity] || '⚪'} ${finding.title}\n\n`;
  explanation += `| Field | Value |\n|-------|-------|\n`;
  explanation += `| **Severity** | ${finding.severity} |\n`;
  explanation += `| **Category** | ${catEmoji[finding.category] || '📋'} ${finding.category} |\n`;
  if (finding.subcategory) explanation += `| **Subcategory** | ${finding.subcategory} |\n`;
  explanation += `| **File** | \`${finding.file_path}:${finding.line}\` |\n`;
  if (finding.confidence) explanation += `| **Confidence** | ${finding.confidence} |\n`;
  explanation += `\n`;

  explanation += `### 📝 Description\n\n${finding.description}\n\n`;

  if (finding.suggestion) {
    explanation += `### 💡 Suggested Fix\n\n${finding.suggestion}\n\n`;
  }

  if (finding.cwe_id) {
    const cweNum = String(finding.cwe_id).replace('CWE-', '');
    explanation += `### 🔗 Reference\n\n[CWE-${cweNum}](https://cwe.mitre.org/data/definitions/${cweNum}.html)\n\n`;
  }

  if (finding.impact) {
    explanation += `### ⚡ Impact\n\n${finding.impact}\n\n`;
  }

  if (finding.metrics) {
    explanation += `### 📊 Metrics\n\n${finding.metrics}\n\n`;
  }

  if (finding.test_example) {
    explanation += `### 🧪 Test Example\n\n\`\`\`\n${finding.test_example}\n\`\`\`\n\n`;
  }

  if (finding.related_files && finding.related_files.length > 0) {
    explanation += `### 🔗 Related Files\n\n${finding.related_files.map(f => `- \`${f}\``).join('\n')}\n\n`;
  }

  return [{ json: { summary_comment: explanation, gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
} catch (error) {
  const cmdData = $('Parse Command').first().json;
  return [{ json: { error: true, summary_comment: `⚠️ Error generating explanation: ${error.message}`, gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
}

// Build agent-specific prompt for rerun
try {
  const cmdData = $('Parse Command').first().json;
  const reviewData = $('Fetch Review (Rerun)').first().json;
  const diffData = $input.first().json;
