    'performance': 'You are a Performance Optimization Specialist. Focus on N+1 queries, algorithmic complexity, memory leaks, caching, async/concurrency patterns, network optimization, resource cleanup. Severity: critical (O(n^2) hot path, resource exhaustion), high (N+1, blocking async), medium (suboptimal algorithm), low (micro-optimization). Return JSON array with: file_path, line, severity, category (performance), subcategory, title, description, suggestion, impact, confidence. Return [] if no issues.',
    'style': 'You are a Code Style Review Specialist. Focus on naming conventions, formatting, documentation, magic numbers, function length, import organization, dead code. Severity: high (unreadable code, missing critical docs), medium (inconsistent naming, missing public docs), low (minor style). Return JSON array with: file_path, line, severity, category (style), subcategory, title, description, suggestion, auto_fixable, confidence. Return [] if no issues.',
    'architecture': 'You are a Software Architecture Review Specialist. Focus on SOLID principles, design patterns, coupling/cohesion, separation of concerns, abstraction layers, dependency injection, API design. Severity: critical (fundamental violation, tight coupling), high (significant concern, missing abstraction), medium (minor issue), low (improvement suggestion). Return JSON array with: file_path, line, severity, category (architecture), subcategory, title, description, suggestion, impact, confidence. Return [] if no issues.',
    'test-coverage': 'You are a Test Coverage and Quality Specialist. Focus on unit test coverage, edge cases, error handling, integration testing, test quality, mock usage. Severity: critical (untested critical path), high (significant coverage gap), medium (partial coverage), low (additional test suggestion). Return JSON array with: file_path, line, severity, category (test-coverage), subcategory, title, description, suggestion, test_example, confidence. Return [] if no issues.',
    'code-quality': 'You are a Code Quality Specialist. Focus on cyclomatic complexity, code smells, duplication, maintainability, error handling, null safety, type safety. Severity: critical (complexity >15, guaranteed error), high (complexity 10-15, significant duplication), medium (moderate complexity), low (minor improvement). Return JSON array with: file_path, line, severity, category (code-quality), subcategory, title, description, suggestion, metrics, confidence. Return [] if no issues.',
    'context': 'You are a Codebase Context Analyst. Focus on file relationships, import/export consistency, API contract changes, migration alignment, config updates, breaking changes, missing related changes, ripple effects. Severity: critical (breaking change without migration), high (missing import, inconsistent API), medium (inconsistent pattern), low (minor inconsistency). Return JSON array with: file_path, line, severity, category (context), subcategory, title, description, suggestion, related_files, confidence. Return [] if no issues.'
  };

  const systemPrompt = agentPrompts[agentName];
  if (!systemPrompt) {
    return [{ json: { error: true, summary_comment: `⚠️ Unknown agent: ${agentName}`, gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
  }

  const userMessage = `Review the following merge request changes:\n\nFiles changed: ${changedFiles.length}\n${diffText}\n\nReturn ONLY a valid JSON array. Return [] if no issues found. Do not include markdown formatting.`;

  return [{ json: {
    agent_name: agentName,
    request_body: {
      model: $('Config').first().json.OPENROUTER_MODEL || 'anthropic/claude-3.5-sonnet',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage }
      ],
      max_tokens: agentName === 'style' ? 6144 : 8192,
      temperature: 0.1
    },
    review_data: reviewData,
    gitlab_url: cmdData.gitlab_url,
    project_id: cmdData.project_id,
    mr_iid: cmdData.mr_iid,
    review_id: reviewData.review_id
  } }];
} catch (error) {
  const cmdData = $('Parse Command').first().json;
  return [{ json: { error: true, summary_comment: `⚠️ Error preparing rerun: ${error.message}`, gitlab_url: cmdData.gitlab_url, project_id: cmdData.project_id, mr_iid: cmdData.mr_iid } }];
}

// Process rerun results - merge new findings back
try {
  const prepData = $('Prepare Rerun Context').first().json;
  const response = $input.first().json;
  const agentName = prepData.agent_name;
  const reviewData = prepData.review_data;

  // Parse existing findings
  let existingFindings = typeof reviewData.findings === 'string' ? JSON.parse(reviewData.findings) : reviewData.findings;

  // Parse new agent response
  let newFindings = [];
  if (response.choices && response.choices[0] && response.choices[0].message) {
    const content = response.choices[0].message.content || '';
    let jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/);
    if (!jsonMatch) {
      jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        const inner = jsonMatch[1].match(/\[\s*\{[\s\S]*\}\s*\]/);
        if (inner) jsonMatch = inner;
      }
    }
    if (jsonMatch) {
      newFindings = JSON.parse(jsonMatch[0]);
    }
  }

  // Map agent name to category
  const categoryMap = {
    'security': 'security', 'performance': 'performance', 'style': 'style',
    'architecture': 'architecture', 'test-coverage': 'test-coverage',
    'code-quality': 'code-quality', 'context': 'context'
  };
  const targetCategory = categoryMap[agentName] || agentName;

  // Remove old findings from this category
  const otherFindings = existingFindings.filter(f => f.category !== targetCategory);

  // Add new findings
  const allFindings = [...otherFindings, ...newFindings];

  // Sort by severity
  const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
  allFindings.sort((a, b) => (severityOrder[a.severity] || 4) - (severityOrder[b.severity] || 4));

  // Renumber
  allFindings.forEach((f, idx) => f.id = idx + 1);

  // Build confirmation
  const oldCount = existingFindings.filter(f => f.category === targetCategory).length;
  const newCount = newFindings.length;
  let confirmation = `## 🔄 Agent Rerun Complete: ${agentName}\n\n`;
  confirmation += `| | Before | After |\n|---|---|---|\n`;
  confirmation += `| **${agentName} findings** | ${oldCount} | ${newCount} |\n`;
  confirmation += `| **Total findings** | ${existingFindings.length} | ${allFindings.length} |\n\n`;

  if (newFindings.length > 0) {
    confirmation += `### New findings:\n`;
    for (const f of newFindings) {
      confirmation += `- **#${f.id}** [${f.severity}] ${f.title} (\`${f.file_path}:${f.line}\`)\n`;
    }
  } else {
    confirmation += `No issues found by ${agentName} agent.\n`;
  }

  confirmation += `\nUse \`/list-findings\` to see the updated list.`;

  return [{ json: {
    summary_comment: confirmation,
    updated_findings: JSON.stringify(allFindings),
    review_id: prepData.review_id,
    gitlab_url: prepData.gitlab_url,
    project_id: prepData.project_id,
    mr_iid: prepData.mr_iid
  } }];
} catch (error) {
  const prepData = $('Prepare Rerun Context').first().json;
  return [{ json: {
    error: true,
    summary_comment: `⚠️ Error processing rerun results: ${error.message}`,
    gitlab_url: prepData.gitlab_url,
    project_id: prepData.project_id,
    mr_iid: prepData.mr_iid
  } }];
}

// Record all findings as accepted in review_history
try {
  const reviewData = $('Fetch Review (Approve All)').first().json;
  const findings = typeof reviewData.findings === 'string' ? JSON.parse(reviewData.findings) : reviewData.findings;
  const cmdData = $('Parse Command').first().json;

  const records = findings.map(f => ({
    review_id: reviewData.review_id,
    project_id: reviewData.project_id,
    mr_iid: reviewData.mr_iid,
    file_path: f.file_path,
    issue_type: f.category,
    issue_subcategory: f.subcategory || null,
    severity: f.severity,
    finding_data: JSON.stringify(f),
    was_accepted: true
  }));

  return records.map(r => ({ json: r }));
} catch (error) {
  return [{ json: { error: true, message: error.message } }];
}

// Record all findings as rejected in review_history
try {
  const reviewData = $('Fetch Review (Reject)').first().json;
  const findings = typeof reviewData.findings === 'string' ? JSON.parse(reviewData.findings) : reviewData.findings;

  const records = findings.map(f => ({
    review_id: reviewData.review_id,
    project_id: reviewData.project_id,
    mr_iid: reviewData.mr_iid,
    file_path: f.file_path,
    issue_type: f.category,
    issue_subcategory: f.subcategory || null,
    severity: f.severity,
    finding_data: JSON.stringify(f),
    was_accepted: false
  }));

  return records.map(r => ({ json: r }));
} catch (error) {
  return [{ json: { error: true, message: error.message } }];
}
